import{_ as a,o as e,a as l,b as i}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"卷积计算","link":"/api/SIMD-API/adv_api/convolution_compute/convolution_compute"},{"text":"Conv3D核函数（Kernel）侧接口","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3d_Kernel"},{"text":"Conv3D模板参数","link":"/api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_template_params"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_template_params.md","filePath":"api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_template_params.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787132628000}'),n={name:"api/SIMD-API/adv_api/convolution_compute/Conv3D_Kernel/Conv3D_template_params.md"};function o(d,t,s,v,p,r){return e(),l("div",null,[...t[0]||(t[0]=[i(`<div><article class="markdown-body"><h1>Conv3D模板参数</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>创建Conv3D对象时需要传入：</p><ul><li>Input、Weight、Output和Bias（可选）的参数类型信息，类型信息通过<a href="Conv3D_usage.html#table19081115275">ConvType</a>来定义，包括：内存逻辑位置、数据格式、数据类型。</li><li>Conv3dParam信息（可选），用于开启不同场景的性能优化模板。<strong>当前暂不支持使用。</strong></li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;class INPUT_TYPE, class WEIGHT_TYPE, class OUTPUT_TYPE, class BIAS_TYPE = biasType, class CONV_CFG = Conv3dParam&gt;
using Conv3D = Conv3dIntfExt&lt;Config&lt;ConvApi::ConvDataType&lt;INPUT_TYPE, WEIGHT_TYPE, OUTPUT_TYPE, BIAS_TYPE, CONV_CFG&gt;&gt;, Impl, Intf&gt;
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>INPUT_TYPE</td><td>输入</td><td>ConvType类型模板参数，指定Input的参数类型信息。</td></tr><tr><td>WEIGHT_TYPE</td><td>输入</td><td>ConvType类型模板参数，指定Weight的参数类型信息。</td></tr><tr><td>OUTPUT_TYPE</td><td>输入</td><td>ConvType类型模板参数，指定Output的参数类型信息。</td></tr><tr><td>BIAS_TYPE</td><td>可选输入</td><td>ConvType类型模板参数，指定Bias的参数类型信息。</td></tr><tr><td>CONV_CFG</td><td>可选输入</td><td>ConvParam类型模板参数，用于开启不同场景的性能优化模板，当前版本只支持基础模板，不开启性能优化。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>无</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>#include &quot;lib/conv/conv3d/conv3d_api.h&quot;

using inputType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::NDC1HWC0, bfloat16_t&gt;;
using weightType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::FRACTAL_Z_3D, bfloat16_t&gt;;
using outputType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::NDC1HWC0, bfloat16_t&gt;;
// 可选参数，如果不带Bias场景，可以不传
using biasType = ConvApi::ConvType&lt;AscendC::TPosition::GM, ConvFormat::ND, float&gt;;
struct ConvCustom : public ConvApi::ConvParam {
    __aicore__ inline ConvCustom(){};
}; // 可选参数，当前版本只支持基础模板，不开启性能优化，可以不传

Conv3dApi::Conv3D&lt;inputType, weightType, outputType, biasType, ConvCustom&gt; conv3dApi;
</code></pre></div></article></div>`,1)])])}const _=a(n,[["render",o]]);export{h as __pageData,_ as default};
